      hu: ["Az egyetlen város Thaiföldön, ahol még mindig közlekednek lovaskocsik.", "Híres kerámiájáról.", "Sok jól megőrzött faháza van."],
      ro: ["Singurul oraș din Thailanda unde încă circulă trăsuri trase de cai.", "Faimos pentru ceramica sa.", "Are multe case din lemn bine conservate."],
      en: ["The only city in Thailand where horse-drawn carriages still operate.", "Famous for its ceramics.", "Has many well-preserved wooden houses."],
