    name: {
      de: "Sakon Nakhon",
      hu: "Szakonnakhon",
      ro: "Sakon Nakhon",
      en: "Sakon Nakhon"},
    descriptionAdvanced: {
      de: "Sakon Nakhon ist eine geschichtsträchtige Stadt im Nordosten Thailands, die in den Ausläufern des Phu Phan Gebirges am Ufer des Nong Han Sees liegt. Die Ursprünge der Siedlung reichen über 3.000 Jahre bis in prähistorische Zeiten zurück, während später Einflüsse der Dvaravati- und Khmer-Kulturen die Region prägten. Das religiöse Zentrum der Stadt ist der Wat Phra That Choeng Chum, ein heiliger Ort, dessen Pagode über den Fußabdrücken von vier Buddhas errichtet worden sein soll. Kulturell ist Sakon Nakhon weltweit für sein Indigo-Gewerbe bekannt, wobei die traditionell gefärbten Stoffe ein wichtiges wirtschaftliches Standbein der lokalen Gemeinschaften darstellen. Ein besonderes Ereignis ist das jährliche Wachsschloss-Festival zum Ende der Regenzeit, bei dem kunstvolle Skulpturen aus Bienenwachs in festlichen Prozessionen präsentiert werden. Die Stadt beherbergt zudem eine bedeutende christliche Gemeinde im Dorf Ban Tha Rae, das für seine Architektur im Kolonialstil und die weihnachtlichen Sternenparaden berühmt ist.",
      hu: "Sakon Nakhon egy történelmi város Thaiföld északkeleti részén, amely a Phu Phan-hegység lábánál, a Nong Han-tó partján fekszik. A település eredete több mint 3000 évre, a történelem előtti időkbe nyúlik vissza, míg később a Dvaravati és Khmer kultúrák hatása formálta a régiót. A város vallási központja a Wat Phra That Choeng Chum, egy szent hely, amelynek pagodája a hiedelem szerint négy Buddha lábnyoma fölé épült. Kulturális szempontból Sakon Nakhon világszerte ismert az indigófestéséről, a hagyományosan festett szövetek a helyi közösségek fontos gazdasági támaszát jelentik. Különleges esemény az évente megrendezett viaszvár-fesztivál az esős évszak végén, ahol méhviaszból készült, művészi szobrokat mutatnak be ünnepi körmenetekben. A város ad otthont egy jelentős keresztény közösségnek is Ban Tha Rae faluban, amely gyarmati stílusú építészetéről és karácsonyi csillagfelvonulásairól híres.",
      ro: "Sakon Nakhon este un oraș plin de istorie din nord-estul Thailandei, situat la poalele munților Phu Phan, pe malul lacului Nong Han. Originile așezării datează de peste 3.000 de ani, din timpuri preistorice, în timp ce mai târziu influențele culturilor Dvaravati și Khmer au modelat regiunea. Centrul religios al orașului este Wat Phra That Choeng Chum, un loc sfânt a cărui pagodă se spune că a fost construită peste urmele a patru Buddha. Din punct de vedere cultural, Sakon Nakhon este cunoscut la nivel mondial pentru industria sa de indigo, țesăturile vopsite tradițional fiind un pilon economic important al comunităților locale. Un eveniment special este festivalul anual al castelelor de ceară de la sfârșitul sezonului ploios, unde sculpturi artistice din ceară de albine sunt prezentate în procesiuni festive. Orașul găzduiește, de asemenea, o comunitate creștină semnificativă în satul Ban Tha Rae, renumit pentru arhitectura sa în stil colonial și paradele de stele de Crăciun.",
      en: "Sakon Nakhon is a city rich in history in northeastern Thailand, located in the foothills of the Phu Phan Mountains on the shores of Nong Han Lake. The settlement's origins date back over 3,000 years to prehistoric times, while later influences from the Dvaravati and Khmer cultures shaped the region. The city's religious center is Wat Phra That Choeng Chum, a sacred site whose pagoda is said to have been built over the footprints of four Buddhas. Culturally, Sakon Nakhon is world-renowned for its indigo industry, with traditionally dyed fabrics being an important economic pillar of local communities. A special event is the annual Wax Castle Festival at the end of the rainy season, where elaborate sculptures made of beeswax are presented in festive processions. The city also hosts a significant Christian community in Ban Tha Rae village, famous for its colonial-style architecture and Christmas star parades.",
      es: "Sakon Nakhon es un elemento notable de la geografía y la cultura tailandesas. Es una ciudad en el noreste de Tailandia junto al lago Nong Han, el lago de agua dulce más grande de Tailandia. Un centro importante para el budismo de la tradición del bosque. Organiza un famoso festival de castillos de cera. El lago es una parte importante de la vida local. Esta ciudad se encuentra entre los asentamientos característicos de Tailandia, a menudo ubicados a lo largo del Chao Phraya o en la costa de Andamán. Como muchos lugares importantes de Tailandia, combina peculiaridades regionales con el legado del Chao Phraya, el Mekong y la tradición budista. Así, contribuye al perfil versátil de Tailandia entre la costa de Andamán, los campos de arroz y los bosques tropicales.",
      pt: "Sakon Nakhon é um elemento notável da geografia e cultura tailandesas. É uma cidade no nordeste da Tailândia junto ao lago Nong Han, o maior lago de água doce da Tailândia. Um centro importante para o budismo da tradição da floresta. Organiza um famoso festival de castelos de cera. O lago é uma parte importante da vida local. Esta cidade está entre os assentamentos característicos da Tailândia, muitas vezes localizados ao longo do Chao Phraya ou na costa de Andamão. Como muitos lugares importantes na Tailândia, combina peculiaridades regionais com o legado do Chao Phraya, do Mekong e da tradição budista. Assim, contribui para o perfil versátil da Tailândia entre a costa de Andamão, arrozais e florestas tropicais.",
      fr: "Sakon Nakhon est un élément remarquable de la géographie et de la culture thaïlandaises. C'est une ville du nord-est de la Thaïlande au bord du lac Nong Han, le plus grand lac d'eau douce de Thaïlande. Un centre important pour le bouddhisme de la tradition forestière. Organise un célèbre festival de châteaux de cire. Le lac est une partie importante de la vie locale. Cette ville compte parmi les établissements caractéristiques de la Thaïlande, souvent situés le long du Chao Phraya ou sur la côte d'Andaman. Comme de nombreux lieux importants en Thaïlande, elle allie particularités régionales et héritage du Chao Phraya, du Mékong et de la tradition bouddhiste. Elle contribue ainsi au profil diversifié de la Thaïlande entre la côte d'Andaman, les rizières et les forêts tropicales.",
    },
