      pt: ["Sakon Nakhon é uma cidade no nordeste da Tailândia junto ao lago Nong Han, o maior lago de água doce da Tailândia.", "Situada no território do Reino da Tailândia.", "Marcada pelo clima de monções do sudeste asiático.", "Ligada ao legado de Sukhothai e Ayutthaya."],
      fr: ["Sakon Nakhon est une ville du nord-est de la Thaïlande au bord du lac Nong Han, le plus grand lac d'eau douce de Thaïlande.", "Située sur le territoire du Royaume de Thaïlande.", "Marquée par le climat de mousson de l'Asie du Sud-Est.", "Liée à l'héritage de Sukhothaï et d'Ayutthaya."],
