    type: "city",
    parent: "TH-16",
    coords: [100.653, 14.798],
    name: {
      de: "Lopburi",
      hu: "Lopburi",
      ro: "Lopburi",
      en: "Lopburi"},
    descriptionAdvanced: {
      de: "Lopburi ist eine der ältesten und historisch bedeutendsten Städte Thailands und liegt etwa 150 Kilometer nördlich von Bangkok in der zentralen Ebene. Die Stadt war ein wichtiges Zentrum der Dvaravati-Kultur und diente später als zweite Hauptstadt des Ayutthaya-Königreichs unter der Herrschaft von König Narai dem Großen im 17. Jahrhundert. Ein markantes Wahrzeichen ist der Phra Prang Sam Yot, ein Tempel im Khmer-Stil mit drei markanten Türmen, der die enge Verbindung zur Angkor-Zivilisation verdeutlicht. Weltweit bekannt ist Lopburi jedoch vor allem als \"Stadt der Affen\", da hunderte von Javaneraffen frei in den Ruinen und Straßen des Stadtzentrums leben. Zu Ehren dieser Tiere findet jedes Jahr das Monkey Banquet Festival statt, bei dem den Affen riesige Mengen an Obst und Speisen serviert werden. Neben den antiken Stätten beherbergt die Stadt den prächtigen Palast von König Narai, der heute als Nationalmuseum dient und europäische Einflüsse in der thailändischen Architektur des 17. Jahrhunderts zeigt.",
      hu: "Lopburi Thaiföld egyik legrégebbi és történelmileg legjelentősebb városa, mintegy 150 kilométerre északra fekszik Bangkoktól a központi síkságon. A város a Dvaravati-kultúra fontos központja volt, majd később az Ayutthaya Királyság második fővárosaként szolgált Narai király uralkodása alatt a 17. században. Egyik jellegzetes látnivalója a Phra Prang Sam Yot, egy három tornyú, Khmer-stílusú templom, amely az Angkor-civilizációval való szoros kapcsolatot mutatja. Lopburi azonban világszerte leginkább a „majmok városaként” ismert, mivel többszáz makákó él szabadon a belváros romjai között és utcáin. Ezen állatok tiszteletére rendezik meg minden évben a majomlakoma-fesztivált, ahol hatalmas mennyiségű gyümölcsöt és ételt szolgálnak fel nekik. Az ókori helyszínek mellett a városban található Narai király pompás palotája is, amely ma nemzeti múzeumként működik, és a 17. századi thaiföldi építészet európai hatásait mutatja be.",
      ro: "Lopburi este unul dintre cele mai vechi și mai semnificative orașe din punct de vedere istoric din Thailanda, situat la aproximativ 150 de kilometri nord de Bangkok, în câmpia centrală. Orașul a fost un centru important al culturii Dvaravati și mai târziu a servit ca a doua capitală a regatului Ayutthaya sub domnia regelui Narai cel Mare în secolul al XVII-lea. Un punct de reper distinctiv este Phra Prang Sam Yot, un templu în stil Khmer cu trei turnuri proeminente, care ilustrează legătura strânsă cu civilizația Angkor. Cu toate acestea, Lopburi este cunoscut la nivel mondial în special ca „orașul maimuțelor”, deoarece sute de macaci trăiesc liberi printre ruinele și străzile centrului orașului. În onoarea acestor animale, are loc în fiecare an Festivalul Banchetului Maimuțelor, unde acestora li se servesc cantități uriașe de fructe și mâncare. Pe lângă siturile antice, orașul găzduiește palatul magnific al regelui Narai, care astăzi servește ca muzeu național și prezintă influențe europene în arhitectura thailandeză din secolul al XVII-lea.",
      en: "Lopburi is one of Thailand's oldest and most historically significant cities, located about 150 kilometers north of Bangkok in the central plains. The city was a major center of the Dvaravati culture and later served as the second capital of the Ayutthaya Kingdom under the reign of King Narai the Great in the 17th century. A prominent landmark is Phra Prang Sam Yot, a Khmer-style temple with three distinctive towers, illustrating the close connection to the Angkor civilization. However, Lopburi is world-famous primarily as the \"City of Monkeys,\" as hundreds of crab-eating macaques live freely among the ruins and streets of the city center. In honor of these animals, the Monkey Banquet Festival is held every year, where vast quantities of fruit and food are served to the monkeys. In addition to the ancient sites, the city houses King Narai's magnificent palace, which now serves as a national museum and showcases European influences in 17th-century Thai architecture.",
      es: "Lopburi es un elemento notable de la geografía y cultura tailandesa. Es una de las ciudades más antiguas de Tailandia, conocida por su gran población de macacos que viven en el centro de la ciudad. Famosa por sus monos. Tiene muchas ruinas de templos antiguos. Fue una segunda capital bajo el rey Narai. Esta ciudad se cuenta entre los asentamientos característicos de Tailandia, situados a menudo a lo largo del Chao Phraya o en la costa de Andamán. Como muchos lugares significativos en Tailandia, este sitio combina rasgos regionales con la herencia del Chao Phraya, el Mekong y la tradición budista. Así, este lugar contribuye al perfil versátil de Tailandia entre la costa de Andamán, los arrozales y los bosques tropicales.",
      pt: "Lopburi é um elemento notável da geografia e cultura tailandesa. É uma das cidades mais antigas da Tailândia, conhecida pela sua grande população de macacos que vivem no centro da cidade. Famosa pelos seus macacos. Possui muitas ruínas de templos antigos. Foi uma segunda capital sob o rei Narai. Esta cidade conta-se entre os assentamentos característicos da Tailândia, situados frequentemente ao longo do Chao Phraya ou na costa de Andaman. Como muitos lugares significativos na Tailândia, este local combina peculiaridades regionais com a herança do Chao Phraya, do Mekong e da tradição budista. Assim, este lugar contribui para o perfil versátil da Tailândia entre a costa de Andaman, arrozais e florestas tropicais.",
      fr: "Lopburi est un élément remarquable de la géographie et de la culture thaïlandaises. C'est l'une des villes les plus anciennes de Thaïlande, connue pour sa grande population de macaques qui vivent au centre-ville. Célèbre pour ses singes. Possède de nombreuses ruines de temples anciens. Fut une seconde capitale sous le roi Narai. Cette ville compte parmi les établissements caractéristiques de Thaïlande, souvent situés le long du Chao Phraya ou sur la côte d'Andaman. Comme de nombreux lieux importants en Thaïlande, ce site associe des particularités régionales à l'héritage du Chao Phraya, du Mékong et de la tradition bouddhiste. Ainsi, ce lieu contribue au profil varié de la Thaïlande entre la côte d'Andaman, les rizières et les forêts tropicales.",
    },
