      hu: ["Kapu a Phi Phi-szigetekhez és a Railay Beach-hez.", "Jellegzetes mészkősziklák jellemzik.", "A Tigrisbarlang Templom egy fő látványosság."],
      ro: ["Poarta de acces către insulele Phi Phi și plaja Railay.", "Caracterizat de stânci de calcar distinctive.", "Templul Peșterii Tigrului este o atracție majoră."],
      en: ["Gateway to Phi Phi Islands and Railay Beach.", "Characterized by distinctive limestone karsts.", "Tiger Cave Temple is a major attraction."],
      es: ["Puerta de entrada a las islas Phi Phi y Railay Beach.", "Caracterizada por impresionantes acantilados de piedra caliza.", "El templo de la Cueva del Tigre es una atracción principal."],
      pt: ["Porta de entrada para as ilhas Phi Phi e Railay Beach.", "Caracterizada por impressionantes falésias de calcário.", "O templo da Caverna do Tigre é uma atração principal."],
