    coords: [99.125, 16.883],
    name: {
      de: "Tak",
      hu: "Tak",
      ro: "Tak",
      en: "Tak"},
    descriptionAdvanced: {
      de: "Tak ist eine geschichtsträchtige Provinzstadt im Nordwesten Thailands, die am Ufer des Ping-Flusses liegt und als Tor zum Norden sowie zum benachbarten Myanmar fungiert. Die Stadt erlangte historische Berühmtheit als Geburtsort von König Taksin dem Großen, der im 18. Jahrhundert die Unabhängigkeit Thailands von den Birmanen wiederherstellte. Strategisch günstig an den Handelswegen gelegen, war Tak jahrhundertelang ein wichtiger Garnisonsort und Schauplatz zahlreicher Schlachten. Geografisch ist die Region durch zerklüftete Gebirgszüge und dichte Wälder geprägt, wobei der Bhumibol-Staudamm, der größte Betonbogendamm Thailands, ein herausragendes Bauwerk der Moderne darstellt. Der Damm wurde 1964 eingeweiht und spielt eine entscheidende Rolle für die Stromerzeugung und Bewässerung Zentralthailands. Kulturell ist die Stadt für das Loy Krathong Sai Festival bekannt, bei dem tausende leuchtende Kokosnussschalen in einer Kette auf dem Ping-Fluss treiben gelassen werden. Tak ist zudem ein wichtiger Knotenpunkt für den grenzüberschreitenden Handel durch die Grenzstadt Mae Sot.",
      hu: "Tak egy történelmi tartományi város Thaiföld északnyugati részén, amely a Ping-folyó partján fekszik, és kapuként szolgál északra, valamint a szomszédos Mianmar felé. A város történelmi hírnevét Nagy Taksin király szülőhelyeként szerezte, aki a 18. században visszaállította Thaiföld függetlenségét a burmaiaktól. A kereskedelmi útvonalak mentén stratégiailag elhelyezkedő Tak évszázadokon át fontos helyőrségi város és számos csata helyszíne volt. Földrajzilag a régiót egyenetlen hegyvonulatok és sűrű erdők jellemzik, ahol a Bhumibol-gát, Thaiföld legnagyobb beton íves gátja a modern építészet kiemelkedő alkotása. A gátat 1964-ben avatták fel, és döntő szerepet játszik Közép-Thaiföld áramtermelésében és öntözésében. Kulturális szempontból a város a Loy Krathong Sai fesztiválról ismert, amely során több ezer világító kókuszdióhéjat eresztenek láncban a Ping-folyóra. Tak emellett a határon átnyúló kereskedelem fontos csomópontja a Mae Sot határvároson keresztül.",
      ro: "Tak este un oraș provincial plin de istorie din nord-vestul Thailandei, situat pe malul râului Ping și servind ca poartă către nord și către Myanmarul vecin. Orașul a câștigat faimă istorică ca fiind locul de naștere al regelui Taksin cel Mare, care a restabilit independența Thailandei de birmani în secolul al XVII-lea. Situat strategic de-a lungul rutelor comerciale, Tak a fost timp de secole un important oraș de garnizoană și locul a numeroase bătălii. Geografic, regiunea este caracterizată de lanțuri muntoase accidentate și păduri dese, barajul Bhumibol, cel mai mare baraj în arc de beton din Thailanda, fiind o structură remarcabilă a epocii moderne. Barajul a fost inaugurat în 1964 și joacă un rol crucial în generarea de energie și irigarea Thailandei centrale. Din punct de vedere cultural, orașul este cunoscut pentru festivalul Loy Krathong Sai, în timpul căruia mii de coji de nucă de cocos luminoase sunt lăsate să plutească în lanț pe râul Ping. Tak este, de asemenea, un nod important pentru comerțul transfrontalier prin orașul de frontieră Mae Sot.",
      en: "Tak is a provincial city rich in history in northwestern Thailand, located on the banks of the Ping River and serving as a gateway to the north and neighboring Myanmar. The city gained historical fame as the birthplace of King Taksin the Great, who restored Thailand's independence from the Burmese in the 18th century. Strategically located along trade routes, Tak was an important garrison town and the site of numerous battles for centuries. Geographically, the region is characterized by rugged mountain ranges and dense forests, with the Bhumibol Dam, Thailand's largest concrete arch dam, being a prominent structure of the modern era. The dam was inaugurated in 1964 and plays a crucial role in power generation and irrigation for central Thailand. Culturally, the city is known for the Loy Krathong Sai festival, during which thousands of glowing coconut shells are floated in a chain on the Ping River. Tak is also an important hub for cross-border trade through the border town of Mae Sot.",
      es: "Tak es un elemento notable de la geografía y cultura tailandesa. Es una ciudad en el oeste de Tailandia, limítrofe con Myanmar, que actúa como un centro comercial vital. Históricamente relevante para el comercio con Birmania. Alberga el festival Loi Krathong Sai. Rodeada de paisajes montañosos. Esta ciudad se cuenta entre los asentamientos característicos de Tailandia, a menudo situados a lo largo del Chao Phraya o en la costa de Andamán. Como muchos lugares importantes de Tailandia, este sitio combina peculiaridades regionales con el legado del Chao Phraya, el Mekong y la tradición budista. Así, contribuye al perfil versátil de Tailandia entre la costa de Andamán, los campos de arroz y las selvas tropicales.",
      pt: "Tak é um elemento notável da geografia e cultura tailandesa. É uma cidade no oeste da Tailândia, fronteiriça com Myanmar, que atua como um centro comercial vital. Historicamente relevante para o comércio com a Birmânia. Acolhe o festival Loi Krathong Sai. Rodeada por paisagens montanhosas. Esta cidade conta-se entre os assentamentos característicos da Tailândia, muitas vezes situados ao longo do Chao Phraya ou na costa de Andamão. Como muitos lugares importantes na Tailândia, este local combina peculiaridades regionais com o legado do Chao Phraya, do Mekong e da tradição budista. Assim, contribui para o perfil versátil da Tailândia entre a costa de Andamão, os campos de arroz e as florestas tropicais.",
      fr: "Tak est un élément remarquable de la géographie et de la culture thaïlandaise. C'est une ville de l'ouest de la Thaïlande, limitrophe du Myanmar, qui agit comme un centre commercial vital. Historiquement importante pour le commerce avec la Birmanie. Accueille le festival Loi Krathong Sai. Entourée de paysages montagneux. Cette ville compte parmi les établissements caractéristiques de la Thaïlande, souvent situés le long du Chao Phraya ou sur la côte d'Andaman. Comme beaucoup d'endroits importants en Thaïlande, ce site combine les particularités régionales avec l'héritage du Chao Phraya, du Mékong et de la tradition bouddhiste. Il contribue ainsi au profil polyvalent de la Thaïlande entre la côte d'Andaman, les rizières et les forêts tropicales.",
    },
