      hu: ["Nagy Taksin király szülőhelye.", "Bhumibol-gát (legnagyobb beton íves gát).", "A Ping-folyó partján fekszik.", "Kapu északra és Mianmar felé.", "Loy Krathong Sai fesztivál.", "Egykori fontos helyőrségi város."],
      ro: ["Locul de naștere al regelui Taksin cel Mare.", "Barajul Bhumibol (cel mai mare baraj în arc).", "Situat pe malul râului Ping.", "Poartă către nord și către Myanmar.", "Festivalul Loy Krathong Sai.", "Fost oraș de garnizoană important."],
      en: ["Birthplace of King Taksin the Great.", "Bhumibol Dam (largest concrete arch dam).", "Located on the banks of the Ping River.", "Gateway to the north and Myanmar.", "Loy Krathong Sai festival.", "Former important garrison town."],
      es: ["Tak es una ciudad en el oeste de Tailandia que limita con Myanmar y sirve como un importante puesto comercial.", "Situada en el territorio del Reino de Tailandia.", "Marcada por el clima monzónico del sudeste asiático.", "Vinculada al legado de Sukhothai y Ayutthaya."],
